请对以下 case 进行三维加权评分。

=== case_id ===
Case-07-sports-event-004

=== 用户原始指令 (query.txt) ===
帮我搞个背景图上面写倒计时的,数字会变的,点一下直接跳应用

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我搞个背景图上面写倒计时的,数字会变的,点一下直接跳应用",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "card": {
      "title": {
        "type": "string",
        "description": "赛事提醒卡片标题",
        "sampleValue": "赛事提醒"
      }
    },
    "countdown": {
      "value": {
        "type": "string",
        "description": "距离赛事开始的倒计时数字展示值",
        "sampleValue": "12"
      },
      "unit": {
        "type": "string",
        "description": "倒计时数字的时间单位",
        "sampleValue": "天"
      }
    },
    "support": {
      "label": {
        "type": "string",
        "description": "底部支撑信息标签",
        "sampleValue": "下一场"
      },
      "value": {
        "type": "string",
        "description": "赛事开始时间摘要",
        "sampleValue": "今晚 20:00"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_run.png",
      "description": "运动/跑步图标，适合用作赛事或运动倒计时卡片的背景图视觉锚点。"
    }
  ]
}

